/// Whether `c` falls in one of `table`'s ranges (sorted, disjoint).
pub(crate) fn in_table(table: &[(char, char)], c: char) -> bool {
    table
        .binary_search_by(|&(lo, hi)| {
            if hi < c {
                std::cmp::Ordering::Less
            } else if lo > c {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_ok()
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Sorted, disjoint, non-adjacent ranges holding `count` code points.
    fn assert_shape(table: &[(char, char)], count: u32) {
        for pair in table.windows(2) {
            assert!((pair[0].1 as u32) + 1 < pair[1].0 as u32, "{pair:?}");
        }
        let total: u32 = table
            .iter()
            .map(|&(lo, hi)| hi as u32 - lo as u32 + 1)
            .sum();
        assert_eq!(total, count);
        for &(lo, hi) in table {
            assert!(lo <= hi && in_table(table, lo) && in_table(table, hi));
            for edge in [lo as u32 - 1, hi as u32 + 1] {
                assert!(
                    !in_table(table, char::from_u32(edge).unwrap()),
                    "U+{edge:04X}"
                );
            }
        }
    }

    #[test]
    fn tables_are_unicode_16() {
        assert_shape(&FORMAT_CHARS, 170);
        assert_shape(&EXTENDED_PICTOGRAPHIC, 3537);
        assert_shape(&COMBINING_MARKS, 2488);
    }

    #[test]
    fn combining_marks_hold_viramas_vowel_signs_and_diacritics() {
        // Devanagari virama (Mn) and vowel sign AA (Mc), Arabic kasra,
        // the combining acute accent.
        for c in ['\u{094D}', '\u{093E}', '\u{0650}', '\u{0301}'] {
            assert!(in_table(&COMBINING_MARKS, c), "U+{:04X}", c as u32);
        }
        for c in ['a', '\u{0627}', '\u{0915}', '\u{200C}', '1', ' '] {
            assert!(!in_table(&COMBINING_MARKS, c), "U+{:04X}", c as u32);
        }
    }
}
